from pathlib import Path
import base64,zlib,json,hashlib
from kaggle.api.kaggle_api_extended import KaggleApi
api=KaggleApi();api.authenticate()
d=Path('/kaggle/working/c07_native');d.mkdir(exist_ok=True)
p=d/'parent';p.mkdir(exist_ok=True)
api.kernels_pull('esthefano/malecns-cognitive-c0-v62-kaggle',path=str(p),metadata=False)
nb=json.loads(next(p.glob('*.ipynb')).read_text());cell=lambda i:''.join(nb['cells'][i]['source'])
assert hashlib.sha256(cell(3).encode()).hexdigest()=='69a606c401d67ff127ca53beb05aa2f8232fb51864f43acfc74225a1fca06e84'
exec(compile(cell(1),'<Cognitive-V62-core>','exec'),globals())
exec(compile(cell(3),'<Cognitive-C0-original>','exec'),globals())
Parent=TokenToKC
q=d/'c02';q.mkdir(exist_ok=True)
api.kernels_pull('esthefano/malecns-cognitive-c02-v62',path=str(q),metadata=False)
source=next(q.glob('*.py')).read_text()
definition='class CompositionalKC(Parent):'+source.split('class CompositionalKC(Parent):',1)[1].split("ns['TokenToKC']=CompositionalKC",1)[0]
exec(compile(definition,'<Cognitive-C02-KC>','exec'),globals())
compressed=''
assert len(compressed)==7088
native_source=zlib.decompress(base64.b64decode(compressed,validate=True))
assert hashlib.sha256(native_source).hexdigest()=='362745c27237d0055dd33dc8e6ae3a4ba7318ce63fb8cfd8ad1527b286bf7336'
exec(compile(native_source,'<Cognitive-C07-native-runner>','exec'),globals())
assert 'make_adapter' not in native_source.decode() and 'adaptive_params' not in native_source.decode()
print('C07 NATIVE SOURCE VERIFIED',flush=True)
result=run_native(seed=7403,epochs=3,output='/kaggle/working/MaleCNS_C07_Native_Smoke_7403',smoke=True)
assert result['status']=='DEV_COMPLETE' and set(result['results'])==set(MODES)
print('C07 SMOKE COMPLETE',flush=True)
